mapper.select:
SELECT
,d.dept_name orgName
FROM car_aduit_free t
left join sys_dept d on d.dept_id = t.org_id and d.del_flag = '0'
WHERE t.del_flag = '0'
 and t.id = #{id}
 and t.confirm_id = #{confirmId}
 and t.car_id = #{carId}
 and t.car_no like concat('%', #{carNo}, '%')
 and t.car_type = #{carType}
 and t.car_vehicle = #{carVehicle}
 and t.org_id = #{orgId}
 and d.dept_name like concat('%', #{orgName}, '%')
 and t.user_ids = #{userIds}
 and t.user_names = #{userNames}
 and t.amount = #{amount}
 and t.back_col1 = #{backCol1}
 and t.back_col2 = #{backCol2}
 and t.status = #{status}
 and t.sort = #{sort}
 and t.eps_id = #{epsId}
 and t.tenant_id = #{tenantId}
 and t.create_by = #{createBy}
order by t.create_time,t.id
